package io.baozhu.copilot.api; import io.baozhu.copilot.security.SqlSafetyValidator; import io.baozhu.copilot.service.CopilotService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1") public class CopilotController {private final CopilotService copilot;private final SqlSafetyValidator sql;public CopilotController(CopilotService c,SqlSafetyValidator s){copilot=c;sql=s;} @PostMapping("/copilot/suggest-rules") public SuggestRulesResponse suggest(@Valid @RequestBody SuggestRulesRequest r){return copilot.suggest(r);} @PostMapping("/sql/review") public SqlReviewResponse review(@Valid @RequestBody SqlReviewRequest r){return sql.review(r.sql(),r.allowedTables());}}